def payment_matches_to_processes(apps, schema_editor):
    """Cada nota com sugestões vira um processo pendente com os boletos dela."""
    PaymentMatch = apps.get_model("documents", "PaymentMatch")
    PaymentProcess = apps.get_model("documents", "PaymentProcess")
    boletos_by_invoice = {}
    for match in PaymentMatch.objects.all():
        boletos_by_invoice.setdefault(match.invoice_id, []).append(match.boleto_id)
    for invoice_id, boleto_ids in boletos_by_invoice.items():
        process = PaymentProcess.objects.create(
            invoice_id=invoice_id, status="PENDING", origin="AUTOMATIC"
        )
        process.boletos.add(*boleto_ids)


